module compute_threshold(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] a0,\n    input [3:0] a1,\n    input [3:0] a2,\n    input [3:0] a3,\n    input [3:0] b0,\n    input [3:0] b1,\n    input [3:0] b2,\n    input [3:0] b3,\n    output reg [15:0] result,\n    output reg done\n);\n    // State declarations\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] S0 = 4'd1;\n    localparam [3:0] S1 = 4'd2;\n    localparam [3:0] S2 = 4'd3;\n    localparam [3:0] S3 = 4'd4;\n    localparam [3:0] S4 = 4'd5;\n    localparam [3:0] S5 = 4'd6;\n    localparam [3:0] S6 = 4'd7;\n    localparam [3:0] S7 = 4'd8;\n    localparam [3:0] S8 = 4'd9;\n    localparam [3:0] S9 = 4'd10;\n    localparam [3:0] DONE = 4'd11;\n\n    reg [3:0] state;\n    reg [15:0] min_scaled;\n    reg [15:0] current_scaled;\n    reg [7:0] sum_a;\n    reg [7:0] sum_b;\n    reg valid;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            min_scaled <= 16'hFFFF;\n            sum_a <= 8'd0;\n            sum_b <= 8'd0;\n            valid <= 1'b0;\n            current_scaled <= 16'd0;\n        end else begin\n            // Default assignments\n            done <= 1'b0;\n            valid <= 1'b0;\n\n            case (state)\n                IDLE: begin\n                    if (start)\n                        min_scaled <= 16'hFFFF;\n                        state <= S0;\n                end\n\n                S0: begin\n                    sum_a = a0 + a1 + a2 + a3;\n                    sum_b = b0 + b1 + b2 + b3;\n                    valid = 1'b1;\n                    current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                    if (valid && current_scaled < min_scaled)\n                        min_scaled <= current_scaled;\n                    state <= S1;\n                end\n\n                S1: begin\n                    if (a0 != a1) begin\n                        sum_a = (a0 > a1 ? a0 : a1) + a2 + a3;\n                        sum_b = (a0 > a1 ? b0 : b1) + b2 + b3;\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S2;\n                end\n\n                S2: begin\n                    if (a0 != a2) begin\n                        sum_a = (a0 > a2 ? a0 : a2) + a1 + a3;\n                        sum_b = (a0 > a2 ? b0 : b2) + b1 + b3;\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S3;\n                end\n\n                S3: begin\n                    if (a0 != a3) begin\n                        sum_a = (a0 > a3 ? a0 : a3) + a1 + a2;\n                        sum_b = (a0 > a3 ? b0 : b3) + b1 + b2;\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S4;\n                end\n\n                S4: begin\n                    if (a1 != a2) begin\n                        sum_a = (a1 > a2 ? a1 : a2) + a0 + a3;\n                        sum_b = (a1 > a2 ? b1 : b2) + b0 + b3;\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S5;\n                end\n\n                S5: begin\n                    if (a1 != a3) begin\n                        sum_a = (a1 > a3 ? a1 : a3) + a0 + a2;\n                        sum_b = (a1 > a3 ? b1 : b3) + b0 + b2;\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S6;\n                end\n\n                S6: begin\n                    if (a2 != a3) begin\n                        sum_a = (a2 > a3 ? a2 : a3) + a0 + a1;\n                        sum_b = (a2 > a3 ? b2 : b3) + b0 + b1;\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S7;\n                end\n\n                S7: begin\n                    if (a0 != a1 && a2 != a3) begin\n                        sum_a = (a0 > a1 ? a0 : a1) + (a2 > a3 ? a2 : a3);\n                        sum_b = (a0 > a1 ? b0 : b1) + (a2 > a3 ? b2 : b3);\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S8;\n                end\n\n                S8: begin\n                    if (a0 != a2 && a1 != a3) begin\n                        sum_a = (a0 > a2 ? a0 : a2) + (a1 > a3 ? a1 : a3);\n                        sum_b = (a0 > a2 ? b0 : b2) + (a1 > a3 ? b1 : b3);\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= S9;\n                end\n\n                S9: begin\n                    if (a0 != a3 && a1 != a2) begin\n                        sum_a = (a0 > a3 ? a0 : a3) + (a1 > a2 ? a1 : a2);\n                        sum_b = (a0 > a3 ? b0 : b3) + (a1 > a2 ? b1 : b2);\n                        valid = 1'b1;\n                        current_scaled = (sum_a * 10'd1000 + sum_b - 8'd1) / sum_b;\n                        if (current_scaled < min_scaled)\n                            min_scaled <= current_scaled;\n                    end\n                    state <= DONE;\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    result <= min_scaled;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule